/* 학습 해설
 * Jenkins 검산·reference와 분포 관찰의 구분
 * 실제 Linux hash helper의 modulo 산술·rotate·block과 tail·seed·길이·wrapper·충돌과 사용 계약을 이해합니다.
 * Python의 32bit masked 상태 표와 index별 tail 누적으로 772byte·196word 사례를 만들어 실제 C와 대조했습니다. 알고리즘 의미를 따른 reference이며 암호 검증이나 전체 충돌률 증명은 아닙니다. 출력 분포·성능·CPU 비용은 별도 질문입니다.
 * 정확한 hash 일치·역 mix 복원·선택 bit 변화의 검사 목적을 나누세요. helper 결과가 같은지와 caller가 실제 key를 비교하는지는 서로 다른 시스템 계약입니다.
 */
static inline u32 jhash2(const u32 *k, u32 length, u32 initval)
{
	u32 a, b, c;

	/* Set up the internal state */
	a = b = c = JHASH_INITVAL + (length<<2) + initval;

	/* Handle most of the key */
	while (length > 3) {
		a += k[0];
		b += k[1];
		c += k[2];
		__jhash_mix(a, b, c);
		length -= 3;
		k += 3;
	}

	/* Handle the last 3 u32's */
	switch (length) {
	case 3: c += k[2];	fallthrough;
	case 2: b += k[1];	fallthrough;
	case 1: a += k[0];
		__jhash_final(a, b, c);
		break;
	case 0:	/* Nothing left to add */
		break;

