/* 학습 해설
 * 스택 추적의 주소 배열·수집과 출력의 분리
 * 커널 실행 경로를 주소 배열로 수집하고 용량·필터·수명·오류·출력 계약을 지키는 스택 추적 기술을 이해합니다.
 * 함수를 호출하면 실행을 되돌아갈 위치 등의 정보가 실행 스택에 남습니다. 스택 추적은 그 실행 경로의 주소를 배열에 모아 문제 발생 위치를 살펴보는 기술입니다. 이 공통 파일은 배열의 용량·건너뛰기·출력을 관리하고 실제 스택을 해석하는 작업은 아키텍처 함수에 맡깁니다. 주소 목록은 함수의 지역 변수나 전체 메모리 내용을 복사한 결과가 아닙니다.
 * unsigned long 배열을 준비하고 용량을 원소 수로 전달합니다. 반환한 개수만 읽고 stack_trace_print로 출력하세요. 예제의 6개 주소는 수집 정책을 시험하는 합성 입력이며 실제 CPU에서 얻은 호출 경로는 아닙니다.
 */
unsigned int stack_trace_save(unsigned long *store, unsigned int size,
			      unsigned int skipnr)
{
	stack_trace_consume_fn consume_entry = stack_trace_consume_entry;
	struct stacktrace_cookie c = {
		.store	= store,
		.size	= size,
		.skip	= skipnr + 1,
	};

	arch_stack_walk(consume_entry, &c, current, NULL);
	return c.len;
}
EXPORT_SYMBOL_GPL(stack_trace_save);

/**
 * stack_trace_save_tsk - Save a task stack trace into a storage array
 * @tsk:	The task to examine
 * @store:	Pointer to storage array
 * @size:	Size of the storage array
 * @skipnr:	Number of entries to skip at the start of the stack trace
 *
 * Return: Number of trace entries stored.
 */
unsigned int stack_trace_save_tsk(struct task_struct *tsk, unsigned long *store,
				  unsigned int size, unsigned int skipnr)

