/* 학습 해설
 * 스택 추적 헤더·선언과 CONFIG 조건
 * 커널 실행 경로를 주소 배열로 수집하고 용량·필터·수명·오류·출력 계약을 지키는 스택 추적 기술을 이해합니다.
 * 헤더는 task_struct와 pt_regs를 전방 선언하고 공개 함수의 인자·반환형을 선언합니다. CONFIG_STACKTRACE일 때 공통 수집·출력 API가 선언되고 CONFIG_ARCH_STACKWALK에 따라 아키텍처 인터페이스 형태가 달라집니다. 함수 원형을 보았다고 해당 설정에서 함수 본문까지 구현되었다고 판단할 수는 없습니다.
 * 헤더의 #ifdef 범위와 C 파일의 #ifdef 범위를 함께 표시하세요. 선언을 통해 용량과 개수의 타입을 읽고 설정이 꺼진 경우 모든 API에 빈 stub가 제공된다고 가정하지 않습니다.
 */
unsigned int stack_trace_save(unsigned long *store, unsigned int size,
			      unsigned int skipnr);
unsigned int stack_trace_save_tsk(struct task_struct *task,
				  unsigned long *store, unsigned int size,
				  unsigned int skipnr);
unsigned int stack_trace_save_regs(struct pt_regs *regs, unsigned long *store,
				   unsigned int size, unsigned int skipnr);
unsigned int stack_trace_save_user(unsigned long *store, unsigned int size);
unsigned int filter_irq_stacks(unsigned long *entries, unsigned int nr_entries);

#ifndef CONFIG_ARCH_STACKWALK
/* Internal interfaces. Do not use in generic code */
struct stack_trace {
	unsigned int nr_entries, max_entries;
	unsigned long *entries;
	unsigned int skip;	/* input argument: How many entries to skip */
};

extern void save_stack_trace(struct stack_trace *trace);
extern void save_stack_trace_regs(struct pt_regs *regs,
				  struct stack_trace *trace);
extern void save_stack_trace_tsk(struct task_struct *tsk,
				struct stack_trace *trace);
extern int save_stack_trace_tsk_reliable(struct task_struct *tsk,
					 struct stack_trace *trace);
extern void save_stack_trace_user(struct stack_trace *trace);

