/* 학습 해설
 * 스택 추적 cookie의 용량·skip·len 불변식
 * 커널 실행 경로를 주소 배열로 수집하고 용량·필터·수명·오류·출력 계약을 지키는 스택 추적 기술을 이해합니다.
 * stacktrace_cookie는 store 포인터와 size 용량, skip 건너뛸 개수, len 실제 저장 개수를 묶습니다. 지정 초기화에서 생략한 len은 0으로 시작합니다. skip이 줄어드는 동안 len은 증가하지 않고 실제 저장 때만 증가하므로 배열에서 유효한 구간은 store[0..len)입니다.
 * 용량 3·skip 2의 상태를 표로 만드세요. 두 주소는 건너뛰고 다음 세 주소만 저장할 수 있습니다. skip과 len을 하나의 카운터로 합치면 반환 개수와 저장 위치의 의미를 잃습니다.
 */
struct stacktrace_cookie {
	unsigned long	*store;
	unsigned int	size;
	unsigned int	skip;
	unsigned int	len;
};

static bool stack_trace_consume_entry(void *cookie, unsigned long addr)
{
	struct stacktrace_cookie *c = cookie;

	if (c->len >= c->size)
		return false;

	if (c->skip > 0) {
		c->skip--;
		return true;
	}
	c->store[c->len++] = addr;
	return c->len < c->size;
}

static bool stack_trace_consume_entry_nosched(void *cookie, unsigned long addr)
{
	if (in_sched_functions(addr))
		return true;

