/* 학습 해설
 * 스택 추적 용량 검사를 skip보다 먼저 하기
 * 커널 실행 경로를 주소 배열로 수집하고 용량·필터·수명·오류·출력 계약을 지키는 스택 추적 기술을 이해합니다.
 * callback은 먼저 len>=size를 검사하고 false로 종료합니다. 그 다음 skip이 양수이면 1을 줄이고 true를 반환합니다. 따라서 size가 0이면 skip이 남아 있어도 줄이지 않고 저장도 하지 않습니다. 유효한 저장 공간이 없는 경우를 먼저 차단하는 분기 순서가 배열 접근을 보호합니다.
 * size 0·skip 2·len 0의 호출을 한 줄씩 따라가세요. 첫 조건에서 종료하므로 store[0] 접근은 없습니다. 유효 용량과 포인터 범위는 caller가 준비해야 하며 함수가 임의 잘못된 포인터를 검증하는 것은 아닙니다.
 */
static bool stack_trace_consume_entry(void *cookie, unsigned long addr)
{
	struct stacktrace_cookie *c = cookie;

	if (c->len >= c->size)
		return false;

	if (c->skip > 0) {
		c->skip--;
		return true;
	}
	c->store[c->len++] = addr;
	return c->len < c->size;
}

static bool stack_trace_consume_entry_nosched(void *cookie, unsigned long addr)
{
	if (in_sched_functions(addr))
		return true;
	return stack_trace_consume_entry(cookie, addr);
}

