/* 학습 해설
 * 사용자 스택 추적·PF_KTHREAD 조기 반환
 * 커널 실행 경로를 주소 배열로 수집하고 용량·필터·수명·오류·출력 계약을 지키는 스택 추적 기술을 이해합니다.
 * ARCH_STACKWALK의 사용자 경로는 current flags에 PF_KTHREAD가 있으면 0으로 종료합니다. 그렇지 않으면 task_pt_regs(current)를 사용자 walker에 전달하고 skip 0으로 주소를 모읍니다. 사용자 주소를 수집하는 기능은 이 공통 파일에서 사용자 메모리의 안전한 읽기 방법까지 구현하는 것은 아닙니다.
 * kernel thread 플래그가 있는 입력과 없는 입력의 walker 호출 횟수를 비교하세요. 합성 사용자 walker는 6개 주소를 제공하며 실제 사용자 스택 접근·fault 처리·보안 검사를 수행하지 않습니다.
 */
unsigned int stack_trace_save_user(unsigned long *store, unsigned int size)
{
	stack_trace_consume_fn consume_entry = stack_trace_consume_entry;
	struct stacktrace_cookie c = {
		.store	= store,
		.size	= size,
	};

	/* Trace user stack if not a kernel thread */
	if (current->flags & PF_KTHREAD)
		return 0;

	arch_stack_walk_user(consume_entry, &c, task_pt_regs(current));

	return c.len;
}
